    "English-Reading & Grammar-GrammarTenses": `
        <div class="n-title">TENSES</div>
        <div class="n-section">
            <div class="n-h3">Key Rules</div>
            <p>• <span class="n-hl">Simple Present:</span> Universal truths and daily habits (The sun rises).</p>
            <p>• <span class="n-hl">Present Perfect:</span> Action completed just now (I have eaten).</p>
            <p>• <span class="n-hl">Past Perfect Continuous:</span> Action started in past, continued to another past point (had been working).</p>
        </div>
    `,
    "English-Reading & Grammar-GrammarModals": `
        <div class="n-title">MODALS</div>
        <div class="n-section">
            <div class="n-h3">Key Usages</div>
            <p>• <span class="n-hl">Must/Ought to:</span> Strong obligation or legal requirement.</p>
            <p>• <span class="n-hl">May/Might:</span> Probability or formal permission.</p>
            <p>• <span class="n-hl">Could/Would:</span> Polite requests in the present.</p>
        </div>
    `,
    "English-Reading & Grammar-GrammarSubjectVerbConcord": `
        <div class="n-title">SUBJECT-VERB CONCORD</div>
        <div class="n-section">
            <div class="n-h3">Tricky Rules</div>
            <p>• <span class="n-hl">Neither/Nor & Either/Or:</span> The verb matches the subject closest to it.</p>
            <p>• <span class="n-hl">As well as / Along with:</span> The verb matches the FIRST subject.</p>
            <p>• <span class="n-hl">Collective Nouns:</span> Team, Jury, Flock take a SINGULAR verb.</p>
        </div>
    `,
    "English-Reading & Grammar-GrammarReportedSpeech": `
        <div class="n-title">REPORTED SPEECH</div>
        <div class="n-section">
            <div class="n-h3">Tense Shifting</div>
            <p>• If reporting verb is in past (said), push the tense back one step (Present -> Past, Past -> Past Perfect).</p>
            <p>• <span class="n-hl">Exceptions:</span> Universal truths (The earth is round) NEVER change tense.</p>
            <p>• Interrogatives (Questions) use 'if' or 'whether', and 'said' becomes 'asked'.</p>
        </div>
    `,
    "English-Reading & Grammar-GrammarDeterminers": `
        <div class="n-title">DETERMINERS</div>
        <div class="n-section">
            <p>• <span class="n-hl">Few / A few:</span> Used for Countable nouns (books, friends).</p>
            <p>• <span class="n-hl">Little / A little / Much:</span> Used for Uncountable nouns (water, time).</p>
            <p>• <span class="n-hl">Any:</span> Strictly used in negative sentences and questions.</p>
        </div>
    `,
